import manifest from './asset-manifest.mjs';
export const HOME_SCENE={url:'assets/burrows-home-v1.jpg',width:900,height:1200,slots:{sun:{x:.525,y:.464},clean:{x:.416,y:.497},sparks:{x:.646,y:.497}}};
export async function loadHomeArt(){const specs={room:HOME_SCENE.url,sun:manifest.sun.url,chog:manifest.chog.url,props:manifest.props.url};return Object.fromEntries(await Promise.all(Object.entries(specs).map(([key,url])=>new Promise((resolve,reject)=>{const img=new Image(),timer=setTimeout(()=>reject(Error('Artwork timed out')),15000);img.onload=()=>{clearTimeout(timer);resolve([key,img]);};img.onerror=()=>{clearTimeout(timer);reject(Error('Artwork unavailable'));};img.src=new URL(url,import.meta.url).href;}))));}
export function drawHomeScene(ctx,images,records,{width=900,height=1200,time=0,reducedMotion=false}={}){
 ctx.clearRect(0,0,width,height);ctx.drawImage(images.room,0,0,width,height);
 if(records.completed){const x=width*.525,y=height*.464,r=width*.15;const light=ctx.createRadialGradient(x,y,2,x,y,r);light.addColorStop(0,'rgba(255,229,153,.4)');light.addColorStop(1,'rgba(255,212,122,0)');ctx.fillStyle=light;ctx.fillRect(x-r,y-r,r*2,r*2);const glow=reducedMotion?0:Math.sin(time*1.8)*1.5;ctx.drawImage(images.sun,...manifest.sun.frame,x-width*.06,y-height*.067+glow,width*.12,height*.135);}
 function medal(x,y,kind){const w=width*.055,h=height*.047;ctx.fillStyle='#5c346a';ctx.beginPath();ctx.moveTo(x-w*.35,y-h*.62);ctx.lineTo(x+w*.35,y-h*.62);ctx.lineTo(x+w*.25,y-h*.05);ctx.lineTo(x,y+h*.06);ctx.lineTo(x-w*.25,y-h*.05);ctx.closePath();ctx.fill();const radius=w*.4,metal=ctx.createRadialGradient(x-radius*.35,y-radius*.2,1,x,y,radius);metal.addColorStop(0,'#fff1ba');metal.addColorStop(.55,'#e6bc71');metal.addColorStop(1,'#8a5739');ctx.fillStyle=metal;ctx.beginPath();ctx.arc(x,y,radius,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#593647';ctx.lineWidth=2;ctx.stroke();if(kind==='sparks')ctx.drawImage(images.props,...manifest.props.frames.gem,x-w*.23,y-h*.27,w*.46,h*.5);else{ctx.strokeStyle='#6b3c4e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-w*.2,y);ctx.lineTo(x-w*.04,y+h*.12);ctx.lineTo(x+w*.23,y-h*.16);ctx.stroke();}}
 if(records.completed&&records.bestClean!==null)medal(width*.416,height*.497,'clean');if(records.completed&&records.bestSparks===8)medal(width*.646,height*.497,'sparks');
 const f=manifest.chog.frames[0],h=height*.138,w=h*f[2]/f[3],breath=reducedMotion?0:Math.sin(time*2.5)*.005;ctx.save();ctx.translate(width*.23,height*.9);ctx.scale(1-breath,1+breath);ctx.drawImage(images.chog,...f,-w/2,-h,w,h);ctx.restore();
}
